import sys

sys.setrecursionlimit(300000)

def solve():
    input = sys.stdin.read
    data = input().split()
    iterator = iter(data)

    try:
        T_str = next(iterator)
    except StopIteration:
        return

    T = int(T_str)
    results = []

    for _ in range(T):
        N = int(next(iterator))
        C = next(iterator)

        adj = [[] for _ in range(N + 1)]
        for _ in range(N - 1):
            u = int(next(iterator))
            v = int(next(iterator))
            adj[u].append(v)
            adj[v].append(u)

        if N == 0:
            results.append("Yes")
            continue

        colors = [''] * (N + 1)
        blue_nodes = []

        for i in range(1, N + 1):
            c = C[i - 1]
            colors[i] = c
            if c == 'B':
                blue_nodes.append(i)

        if len(blue_nodes) < 2:
            results.append("Yes")
            continue

        parent = [0] * (N + 1)
        depth = [0] * (N + 1)
        order = []
        stack = [blue_nodes[0]]
        visited = [False] * (N + 1)
        visited[blue_nodes[0]] = True

        while stack:
            u = stack.pop()
            order.append(u)
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    parent[v] = u
                    depth[v] = depth[u] + 1
                    stack.append(v)

        def get_lca(u, v):
            while depth[u] > depth[v]:
                u = parent[u]
            while depth[v] > depth[u]:
                v = parent[v]
            while u != v:
                u = parent[u]
                v = parent[v]
            return u

        has_red = [False] * (N + 1)
        has_green = [False] * (N + 1)

        for i in range(1, N + 1): c = colors[i]; has_red[i] = (c == 'R'); has_green[i] = (c == 'G')

        def check_path(u, v):
            lca = get_lca(u, v)
            curr = u
            found_r = False
            found_g = False
            while curr != lca:
                if has_red[curr]:
                    found_r = True
                if has_green[curr]:
                    found_g = True
                curr = parent[curr]
            if has_red[lca]:
                found_r = True
            if has_green[lca]:
                found_g = True

            curr = v
            while curr != lca:
                if has_red[curr]: found_r = True
                if has_green[curr]: found_g = True
                curr = parent[curr]

            return found_r and found_g

        valid = True
        for i in range(len(blue_nodes)):
            if not valid:
                break
            u = blue_nodes[i]
            for j in range(i + 1, len(blue_nodes)):
                v = blue_nodes[j]
                if not check_path(u, v):
                    valid = False
                    break

        results.append("Yes" if valid else "No")

    for res in results:
        print(res)

if __name__ == "__main__":
    solve()
